{
  "fixture_variation": 5,
  "bug": {
    "summary": "Off-by-one in pagination slice drops the final page of results",
    "location": "src/pagination.py::paginate",
    "repro": "paginate(items=range(10), page=3, per_page=4) returns [] instead of [8, 9]"
  },
  "fix": {
    "diff": "--- a/src/pagination.py\n+++ b/src/pagination.py\n@@\n-    start = page * per_page\n-    end = start + per_page\n+    start = (page - 1) * per_page\n+    end = start + per_page\n     return items[start:end]",
    "rationale": "Page numbers are 1-based; the previous 0-based start index skipped the first page and pushed the last page out of range."
  },
  "test": {
    "file": "tests/test_pagination.py",
    "added": "def test_last_page_partial():\n    assert paginate(list(range(10)), page=3, per_page=4) == [8, 9]",
    "result": "1 passed (simulated)"
  },
  "review": {
    "status": "ready_for_review",
    "risks": [
      "Callers relying on the old 0-based behavior would need updating (none found in repo scan).",
      "No validation for page < 1; consider raising ValueError in a follow-up."
    ],
    "evidence_level": "simulation_only",
    "business_status": "not_measured"
  }
}
